   433→import { useState, useEffect, useMemo, useCallback } from 'react';
   434→import type { Kurse, Teilnehmer, Kursanmeldung, Dozenten, Raeume, Anmeldungen } from '@/types/app';
   435→import { LivingAppsService } from '@/services/livingAppsService';
   436→
   437→export function useDashboardData() {
   438→  const [kurse, setKurse] = useState<Kurse[]>([]);
   439→  const [teilnehmer, setTeilnehmer] = useState<Teilnehmer[]>([]);
   440→  const [kursanmeldung, setKursanmeldung] = useState<Kursanmeldung[]>([]);
   441→  const [dozenten, setDozenten] = useState<Dozenten[]>([]);
   442→  const [raeume, setRaeume] = useState<Raeume[]>([]);
   443→  const [anmeldungen, setAnmeldungen] = useState<Anmeldungen[]>([]);
   444→  const [loading, setLoading] = useState(true);
   445→  const [error, setError] = useState<Error | null>(null);
   446→
   447→  const fetchAll = useCallback(async () => {
   448→    setError(null);
   449→    try {
   450→      const [kurseData, teilnehmerData, kursanmeldungData, dozentenData, raeumeData, anmeldungenData] = await Promise.all([
   451→        LivingAppsService.getKurse(),
   452→        LivingAppsService.getTeilnehmer(),
   453→        LivingAppsService.getKursanmeldung(),
   454→        LivingAppsService.getDozenten(),
   455→        LivingAppsService.getRaeume(),
   456→        LivingAppsService.getAnmeldungen(),
   457→      ]);
   458→      setKurse(kurseData);
   459→      setTeilnehmer(teilnehmerData);
   460→      setKursanmeldung(kursanmeldungData);
   461→      setDozenten(dozentenData);
   462→      setRaeume(raeumeData);
   463→      setAnmeldungen(anmeldungenData);
   464→    } catch (err) {
   465→      setError(err instanceof Error ? err : new Error('Fehler beim Laden der Daten'));
   466→    } finally {
   467→      setLoading(false);
   468→    }
   469→  }, []);
   470→
   471→  useEffect(() => { fetchAll(); }, [fetchAll]);
   472→
   473→  const kurseMap = useMemo(() => {
   474→    const m = new Map<string, Kurse>();
   475→    kurse.forEach(r => m.set(r.record_id, r));
   476→    return m;
   477→  }, [kurse]);
   478→
   479→  const teilnehmerMap = useMemo(() => {
   480→    const m = new Map<string, Teilnehmer>();
   481→    teilnehmer.forEach(r => m.set(r.record_id, r));
   482→    return m;
   483→  }, [teilnehmer]);
   484→
   485→  const dozentenMap = useMemo(() => {
   486→    const m = new Map<string, Dozenten>();
   487→    dozenten.forEach(r => m.set(r.record_id, r));
   488→    return m;
   489→  }, [dozenten]);
   490→
