   572→// ---- KursDialog ----
   573→import type { Dozenten, Raeume } from '@/types/app';
   574→
   575→function KursDialog({
   576→  open,
   577→  onClose,
   578→  editingKurs,
   579→  dozenten,
   580→  raeume,
   581→  onSaved,
   582→}: {
   583→  open: boolean;
   584→  onClose: () => void;
   585→  editingKurs: Kurse | null;
   586→  dozenten: Dozenten[];
   587→  raeume: Raeume[];
   588→  onSaved: () => void;
   589→}) {
   590→  const [form, setForm] = useState({
   591→    titel: editingKurs?.fields.titel ?? '',
   592→    beschreibung: editingKurs?.fields.beschreibung ?? '',
   593→    startdatum: editingKurs?.fields.startdatum ?? '',
   594→    enddatum: editingKurs?.fields.enddatum ?? '',
   595→    max_teilnehmer: editingKurs?.fields.max_teilnehmer?.toString() ?? '',
   596→    preis: editingKurs?.fields.preis?.toString() ?? '',
   597→    dozent: editingKurs?.fields.dozent ? (extractRecordId(editingKurs.fields.dozent) ?? 'none') : 'none',
   598→    raum: editingKurs?.fields.raum ? (extractRecordId(editingKurs.fields.raum) ?? 'none') : 'none',
   599→  });
   600→  const [saving, setSaving] = useState(false);
   601→
   602→  // Reset when dialog opens
   603→  useState(() => {
   604→    setForm({
   605→      titel: editingKurs?.fields.titel ?? '',
   606→      beschreibung: editingKurs?.fields.beschreibung ?? '',
   607→      startdatum: editingKurs?.fields.startdatum ?? '',
   608→      enddatum: editingKurs?.fields.enddatum ?? '',
   609→      max_teilnehmer: editingKurs?.fields.max_teilnehmer?.toString() ?? '',
   610→      preis: editingKurs?.fields.preis?.toString() ?? '',
   611→      dozent: editingKurs?.fields.dozent ? (extractRecordId(editingKurs.fields.dozent) ?? 'none') : 'none',
   612→      raum: editingKurs?.fields.raum ? (extractRecordId(editingKurs.fields.raum) ?? 'none') : 'none',
   613→    });
   614→  });
   615→
   616→  const handleSave = async () => {
   617→    setSaving(true);
   618→    try {
   619→      const fields: Kurse['fields'] = {
   620→        titel: form.titel || undefined,
   621→        beschreibung: form.beschreibung || undefined,
   622→        startdatum: form.startdatum || undefined,
   623→        enddatum: form.enddatum || undefined,
   624→        max_teilnehmer: form.max_teilnehmer ? Number(form.max_teilnehmer) : undefined,
   625→        preis: form.preis ? Number(form.preis) : undefined,
   626→        dozent: form.dozent !== 'none' ? createRecordUrl(APP_IDS.DOZENTEN, form.dozent) : undefined,
   627→        raum: form.raum !== 'none' ? createRecordUrl(APP_IDS.RAEUME, form.raum) : undefined,
   628→      };
   629→      if (editingKurs) {
   630→        await LivingAppsService.updateKurseEntry(editingKurs.record_id, fields);
   631→      } else {
   632→        await LivingAppsService.createKurseEntry(fields);
   633→      }
   634→      onSaved();
   635→    } finally {
   636→      setSaving(false);
   637→    }
   638→  };
   639→
   640→  return (
   641→    <Dialog open={open} onOpenChange={v => !v && onClose()}>
   642→      <DialogContent className="max-w-md">
   643→        <DialogHeader>
   644→          <DialogTitle>{editingKurs ? 'Kurs bearbeiten' : 'Neuen Kurs anlegen'}</DialogTitle>
   645→        </DialogHeader>
   646→        <div className="space-y-3 py-2">
   647→          <div className="space-y-1">
   648→            <Label className="text-xs font-500">Kurstitel</Label>
   649→            <Input value={form.titel} onChange={e => setForm(f => ({ ...f, titel: e.target.value }))} placeholder="Titel…" />
   650→          </div>
   651→          <div className="space-y-1">
   652→            <Label className="text-xs font-500">Beschreibung</Label>
   653→            <Input value={form.beschreibung} onChange={e => setForm(f => ({ ...f, beschreibung: e.target.value }))} placeholder="Beschreibung…" />
   654→          </div>
   655→          <div className="grid grid-cols-2 gap-3">
   656→            <div className="space-y-1">
   657→              <Label className="text-xs font-500">Startdatum</Label>
   658→              <Input type="date" value={form.startdatum} onChange={e => setForm(f => ({ ...f, startdatum: e.target.value }))} />
   659→            </div>
   660→            <div className="space-y-1">
   661→              <Label className="text-xs font-500">Enddatum</Label>
   662→              <Input type="date" value={form.enddatum} onChange={e => setForm(f => ({ ...f, enddatum: e.target.value }))} />
   663→            </div>
   664→          </div>
   665→          <div className="grid grid-cols-2 gap-3">
   666→            <div className="space-y-1">
   667→              <Label className="text-xs font-500">Max. Teilnehmer</Label>
   668→              <Input type="number" value={form.max_teilnehmer} onChange={e => setForm(f => ({ ...f, max_teilnehmer: e.target.value }))} placeholder="0" />
   669→            </div>
   670→            <div className="space-y-1">
   671→              <Label className="text-xs font-500">Preis (€)</Label>
   672→              <Input type="number" value={form.preis} onChange={e => setForm(f => ({ ...f, preis: e.target.value }))} placeholder="0.00" />
   673→            </div>
   674→          </div>
   675→          <div className="space-y-1">
   676→            <Label className="text-xs font-500">Dozent</Label>
   677→            <Select value={form.dozent} onValueChange={v => setForm(f => ({ ...f, dozent: v }))}>
   678→              <SelectTrigger className="text-sm"><SelectValue placeholder="Dozent wählen" /></SelectTrigger>
   679→              <SelectContent>
   680→                <SelectItem value="none">Kein Dozent</SelectItem>
   681→                {dozenten.map(d => (
   682→                  <SelectItem key={d.record_id} value={d.record_id}>
   683→                    {d.fields.vorname} {d.fields.nachname}
   684→                  </SelectItem>
   685→                ))}
   686→              </SelectContent>
   687→            </Select>
   688→          </div>
   689→          <div className="space-y-1">
   690→            <Label className="text-xs font-500">Raum</Label>
   691→            <Select value={form.raum} onValueChange={v => setForm(f => ({ ...f, raum: v }))}>
   692→              <SelectTrigger className="text-sm"><SelectValue placeholder="Raum wählen" /></SelectTrigger>
   693→              <SelectContent>
   694→                <SelectItem value="none">Kein Raum</SelectItem>
   695→                {raeume.map(r => (
   696→                  <SelectItem key={r.record_id} value={r.record_id}>
   697→                    {r.fields.raumname}{r.fields.gebaeude ? ` · ${r.fields.gebaeude}` : ''}
   698→                  </SelectItem>
   699→                ))}
   700→              </SelectContent>
   701→            </Select>
   702→          </div>
   703→        </div>
   704→        <DialogFooter>
   705→          <Button variant="outline" onClick={onClose} disabled={saving}>Abbrechen</Button>
   706→          <Button onClick={handleSave} disabled={saving || !form.titel}>
   707→            {saving ? 'Speichern…' : 'Speichern'}
   708→          </Button>
   709→        </DialogFooter>
   710→      </DialogContent>
   711→    </Dialog>
   712→  );
   713→}
