   723→  onSaved,
   724→}: {
   725→  open: boolean;
   726→  onClose: () => void;
   727→  kursId: string | null;
   728→  teilnehmer: Teilnehmer[];
   729→  onSaved: () => void;
   730→}) {
   731→  const [form, setForm] = useState({
   732→    teilnehmer_id: 'none',
   733→    anmeldedatum: new Date().toISOString().slice(0, 10),
   734→    bezahlt: false,
   735→  });
   736→  const [saving, setSaving] = useState(false);
   737→
   738→  const handleSave = async () => {
   739→    if (!kursId) return;
   740→    setSaving(true);
   741→    try {
   742→      const fields: Anmeldungen['fields'] = {
   743→        kurs: createRecordUrl(APP_IDS.KURSE, kursId),
   744→        teilnehmer: form.teilnehmer_id !== 'none'
   745→          ? createRecordUrl(APP_IDS.TEILNEHMER, form.teilnehmer_id)
   746→          : undefined,
   747→        anmeldedatum: form.anmeldedatum || undefined,
   748→        bezahlt: form.bezahlt,
   749→      };
   750→      await LivingAppsService.createAnmeldungenEntry(fields);
   751→      onSaved();
   752→    } finally {
   753→      setSaving(false);
   754→    }
   755→  };
   756→
   757→  return (
   758→    <Dialog open={open} onOpenChange={v => !v && onClose()}>
   759→      <DialogContent className="max-w-sm">
   760→        <DialogHeader>
   761→          <DialogTitle>Neue Anmeldung</DialogTitle>
   762→        </DialogHeader>
   763→        <div className="space-y-3 py-2">
   764→          <div className="space-y-1">
   765→            <Label className="text-xs font-500">Teilnehmer</Label>
   766→            <Select value={form.teilnehmer_id} onValueChange={v => setForm(f => ({ ...f, teilnehmer_id: v }))}>
   767→              <SelectTrigger className="text-sm"><SelectValue placeholder="Teilnehmer wählen" /></SelectTrigger>
   768→              <SelectContent>
   769→                <SelectItem value="none">Kein Teilnehmer</SelectItem>
   770→                {teilnehmer.map(t => (
   771→                  <SelectItem key={t.record_id} value={t.record_id}>
   772→                    {t.fields.vorname} {t.fields.nachname}
   773→                  </SelectItem>
   774→                ))}
   775→              </SelectContent>
   776→            </Select>
   777→          </div>
   778→          <div className="space-y-1">
   779→            <Label className="text-xs font-500">Anmeldedatum</Label>
   780→            <Input type="date" value={form.anmeldedatum} onChange={e => setForm(f => ({ ...f, anmeldedatum: e.target.value }))} />
   781→          </div>
   782→          <div className="flex items-center gap-2">
   783→            <Checkbox
   784→              id="bezahlt"
   785→              checked={form.bezahlt}
   786→              onCheckedChange={v => setForm(f => ({ ...f, bezahlt: v === true }))}
   787→            />
   788→            <Label htmlFor="bezahlt" className="text-sm cursor-pointer">Bereits bezahlt</Label>
   789→          </div>
   790→        </div>
   791→        <DialogFooter>
   792→          <Button variant="outline" onClick={onClose} disabled={saving}>Abbrechen</Button>
   793→          <Button onClick={handleSave} disabled={saving}>
   794→            {saving ? 'Speichern…' : 'Anmelden'}
   795→          </Button>
   796→        </DialogFooter>
   797→      </DialogContent>
   798→    </Dialog>
   799→  );
   800→}
   801→
   802→// ---- Confirm Delete ----
   803→function ConfirmDeleteDialog({
   804→  open,
   805→  type,
   806→  onCancel,
   807→  onConfirm,
   808→  isSubmitting,
   809→  setIsSubmitting,
   810→}: {
   811→  open: boolean;
   812→  type: 'kurs' | 'anmeldung';
   813→  onCancel: () => void;
   814→  onConfirm: () => Promise<void>;
   815→  isSubmitting: boolean;
   816→  setIsSubmitting: (v: boolean) => void;
   817→}) {
   818→  const handleConfirm = async () => {
   819→    setIsSubmitting(true);
   820→    try {
   821→      await onConfirm();
   822→    } finally {
   823→      setIsSubmitting(false);
   824→    }
   825→  };
   826→
   827→  return (
   828→    <Dialog open={open} onOpenChange={v => !v && onCancel()}>
   829→      <DialogContent className="max-w-sm">
   830→        <DialogHeader>
   831→          <DialogTitle>{type === 'kurs' ? 'Kurs löschen?' : 'Anmeldung löschen?'}</DialogTitle>
   832→        </DialogHeader>
   833→        <p className="text-sm text-muted-foreground py-2">
   834→          {type === 'kurs'
   835→            ? 'Dieser Kurs und alle zugehörigen Daten werden unwiderruflich gelöscht.'
   836→            : 'Diese Anmeldung wird unwiderruflich gelöscht.'}
   837→        </p>
   838→        <DialogFooter>
   839→          <Button variant="outline" onClick={onCancel} disabled={isSubmitting}>Abbrechen</Button>
   840→          <Button variant="destructive" onClick={handleConfirm} disabled={isSubmitting}>
   841→            {isSubmitting ? 'Löschen…' : 'Löschen'}
   842→          </Button>
   843→        </DialogFooter>
   844→      </DialogContent>
   845→    </Dialog>
   846→  );
   847→}
   848→
   849→// ---- Loading / Error ----
   850→function DashboardSkeleton() {
   851→  return (
   852→    <div className="space-y-6">
   853→      <div className="flex items-center justify-between">
   854→        <Skeleton className="h-8 w-48" />
   855→        <Skeleton className="h-9 w-36" />
   856→      </div>
   857→      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
   858→        {[...Array(4)].map((_, i) => <Skeleton key={i} className="h-24 rounded-2xl" />)}
   859→      </div>
   860→      <Skeleton className="h-64 rounded-2xl" />
   861→    </div>
   862→  );
   863→}
   864→
   865→function DashboardError({ error, onRetry }: { error: Error; onRetry: () => void }) {
   866→  return (
   867→    <div className="flex flex-col items-center justify-center py-24 gap-4">
   868→      <div className="w-12 h-12 rounded-2xl bg-destructive/10 flex items-center justify-center">
   869→        <AlertCircle size={22} className="text-destructive" />
   870→      </div>
   871→      <div className="text-center">
   872→        <h3 className="font-semibold text-foreground mb-1">Fehler beim Laden</h3>
